#!/usr/bin/env python3
"""Produce an INACTIVE exact-source guard proposal after explicit root admission; never activate."""
import argparse,ast,datetime,difflib,hashlib,importlib.util,json,pathlib,re,subprocess,sys
sys.dont_write_bytecode=True
ROOT=pathlib.Path('/Users/tianpan/projects/bex')
ACTIVE=pathlib.Path('/tmp/bex-m188-prepare-adoption.py')
AGGREGATE=pathlib.Path('/tmp/bex-m188-published-acceptance.json')
BASE_GUARD='3fe1b2bd1a5a44ba7711f33546c1cf1db5539bdb36f08b2e4c8e40ff56e42c58'
OLD_SOURCE='846a56038319f1b5c212d1fcda8291d20e49c2b0'
OLD_WORKFLOW='39b2ebac4a5b4d502db7a8245d90a9031db779ba4cea6da55588cb056abe469f'
PROFILE={'.github/workflows/native-base-image.yml':'a85673654cd0b69e35797791fe6e87906e5625637bcf6b43b4937e4730b29547','.github/scripts/native-oci-stage.py':'891d6581c29c8d3d39be80b60882c0e05f974e167c5f1784713b69d3fa159d59','.github/scripts/test_native_oci_stage.py':'d1e7f01511863391f3c8a2bcc8c1f80e42c30fe3f04fd1dc84f598e2acd69803','.github/scripts/test_native_oci_workflow.py':'6538a7ba0273c65593933f0d9d34acdf0f788380c4f09ed620abf1f1519e37ad'}
h=lambda b:hashlib.sha256(b).hexdigest()
def create(p,b):
 with p.open('xb') as f:f.write(b)
def load(name,p):
 sp=importlib.util.spec_from_file_location(name,p);m=importlib.util.module_from_spec(sp);sp.loader.exec_module(m);return m
def functions(raw):
 text=raw.decode();return {n.name:ast.get_source_segment(text,n) for n in ast.parse(text).body if isinstance(n,ast.FunctionDef)}
def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--source',required=True);p.add_argument('--admission',type=pathlib.Path,required=True);p.add_argument('--admission-sha256',required=True);p.add_argument('--closure-review',type=pathlib.Path,required=True);p.add_argument('--closure-review-sha256',required=True);p.add_argument('--output-dir',type=pathlib.Path,required=True);a=p.parse_args();assert re.fullmatch('[0-9a-f]{40}',a.source);before=ACTIVE.read_bytes();receipt_bytes=AGGREGATE.read_bytes();assert h(before)==BASE_GUARD;assert h(receipt_bytes)=='64249b676294f1f710a63e96d4356608895465524f2c45c53936dfcc04866e78';receipt=json.loads(receipt_bytes);assert len(receipt['verified'])==9 and a.source not in receipt['accepted_sources']
 assert h(a.admission.read_bytes())==a.admission_sha256 and h(a.closure_review.read_bytes())==a.closure_review_sha256
 admission=json.loads(a.admission.read_bytes());closure=json.loads(a.closure_review.read_bytes());assert admission['source']==closure['source']==a.source and admission['admitted'] is True;assert set(admission['roles'])=={'producer:all11','verification:all11'};assert admission['workflow_sha256']==PROFILE['.github/workflows/native-base-image.yml']
 subprocess.run(['git','-C',str(ROOT),'merge-base','--is-ancestor',OLD_SOURCE,a.source],check=True,capture_output=True)
 for path,expected in PROFILE.items():
  source=subprocess.check_output(['git','-C',str(ROOT),'show',a.source+':'+path]);assert h(source)==expected and (ROOT/path).read_bytes()==source,path
 text=before.decode();line="RECOVERY_WORKFLOW = '"+OLD_SOURCE+"'";assert text.count(line)==1;text=text.replace(line,"RECOVERY_WORKFLOW = '"+a.source+"'",1);line="REVIEWED_WORKFLOW_SHA256 = '"+OLD_WORKFLOW+"'";assert text.count(line)==1;text=text.replace(line,"REVIEWED_WORKFLOW_SHA256 = '"+PROFILE['.github/workflows/native-base-image.yml']+"'",1);needle='APPROVED_PRODUCER_SOURCES = {FIXED_RECIPE, RECOVERY_WORKFLOW, ';assert text.count(needle)==1;text=text.replace(needle,needle+repr(OLD_SOURCE)+', ',1);proposed=text.encode();assert functions(before)==functions(proposed),'Function source bytes changed';compile(text,'INACTIVE-OCI-source-profile','exec')
 out=a.output_dir.resolve();assert out.is_relative_to(pathlib.Path('/tmp').resolve()) and not out.exists();out.mkdir();guard=out/(h(proposed)+'.py');create(guard,proposed);old=load('profile_before',ACTIVE);new=load('profile_after',guard);assert new.APPROVED_PRODUCER_SOURCES==old.APPROVED_PRODUCER_SOURCES|{a.source} and new.APPROVED_VERIFICATION_SOURCES==old.APPROVED_VERIFICATION_SOURCES|{a.source};assert new.PRODUCER_RUNTIME_RESTRICTIONS==old.PRODUCER_RUNTIME_RESTRICTIONS;assert new.HISTORICAL_INSTALL_PRODUCERS==old.HISTORICAL_INSTALL_PRODUCERS and a.source not in new.HISTORICAL_INSTALL_PRODUCERS
 diff=''.join(difflib.unified_diff(before.decode().splitlines(True),text.splitlines(True),fromfile='ACTIVE-'+BASE_GUARD,tofile='INACTIVE-'+h(proposed)));create(out/'guard.diff',diff.encode());record={'schema':'bex.m188.INACTIVE-exact-OCI-source-migration/v1','at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'source':a.source,'admitted_root_roles_not_yet_activated':True,'root_admission':{'file':str(a.admission),'sha256':a.admission_sha256},'external_exact_publisher_closure_review':{'file':str(a.closure_review),'sha256':a.closure_review_sha256,'must_include_new_helper_and_tests':True},'publisher_profile':PROFILE,'old_guard_sha256':BASE_GUARD,'proposed_guard':{'file':str(guard),'sha256':h(proposed)},'guard_diff':{'file':str(out/'guard.diff'),'sha256':h(diff.encode())},'all_function_source_bytes_unchanged':True,'historical_846_explicit_literal_retained':True,'all_old_roles_plus_only_exact_new_source':True,'historical_install_exception_not_extended_to_new_source':True,'context_unchanged_sha256':h(receipt_bytes),'source_policy_aggregate_append_pending_separate_root_authorization':True,'accepted_count_unchanged':9,'activation_performed':False,'candidate_promotion_or_adoption':False,'next_authorized_checks':'Only after exact proposal/rootactivationapproval: freezebefore/afteraccepted_sources-onlyappend and full9guards+realincomplete11copyrefusal.','scope':'TEMP inactive proposal only; no guard/context/aggregate/proof/repository/board/remote writes.'};create(out/'proposal.json',(json.dumps(record,indent=2)+'\n').encode());assert ACTIVE.read_bytes()==before and AGGREGATE.read_bytes()==receipt_bytes;print(json.dumps({'proposal':str(guard),'guard_sha256':h(proposed),'report':str(out/'proposal.json'),'report_sha256':h((out/'proposal.json').read_bytes()),'diff_sha256':h(diff.encode()),'NOT_ACTIVATED':True}))
if __name__=='__main__':main()
